function clockPause(){if(reviewClock.since!==null){reviewClock.elapsed+=performance.now()-reviewClock.since;reviewClock.since=null;}}
function clockStart(id){clockPause();reviewClock={id,elapsed:0,since:document.visibilityState==='visible'?performance.now():null};}
function clockMs(){return Math.round(reviewClock.elapsed+(reviewClock.since===null?0:performance.now()-reviewClock.since));}
