function showStorageConflict(){
 storageConflict=true;storageError='Данные изменились в другой вкладке. Скачайте текущий снимок и обновите страницу.';importController?.abort();
 let el=document.getElementById('storage-conflict-root');if(!el){el=document.createElement('aside');el.id='storage-conflict-root';el.className='storage-conflict';el.setAttribute('role','alert');document.body.appendChild(el);}
 el.innerHTML='<strong>Данные изменились в другой вкладке</strong><p>Запись из этой вкладки остановлена. Скачайте её снимок с черновиками, затем обновите страницу, чтобы увидеть актуальные данные.</p><div><button class="button secondary" data-action="conflict-export">Скачать снимок JSON</button><button class="button primary" data-action="conflict-reload">Обновить страницу</button></div>';
}
function showStorageProblem(){
 let el=document.getElementById('storage-problem-root');if(!el){el=document.createElement('aside');el.id='storage-problem-root';el.className='storage-conflict';el.setAttribute('role','alert');document.body.appendChild(el);}
 el.innerHTML=storageCorrupt?'<strong>Локальные данные не удалось прочитать</strong><p>Исходный снимок сохранён и не будет перезаписан новой проверкой. Скачайте его для восстановления или загрузите резервную копию.</p><div><button class="button secondary" data-action="corrupt-export">Скачать исходный снимок</button><button class="button primary" data-action="corrupt-import">Восстановить из копии</button><button class="text-button" data-action="corrupt-reset">Начать заново</button></div>':`<strong>Данные не записаны в хранилище</strong><p>${esc(storageError)}</p><div><button class="button secondary" data-action="conflict-export">Скачать текущий снимок</button></div>`;
}
function canWrite({recover=false}={}){
 try{if(storageConflict||localStorage.getItem(storageKey)!==storageSnapshot){showStorageConflict();return false;}
 if(storageCorrupt&&!recover){storageError='Повреждённый снимок защищён от перезаписи. Используйте восстановление из копии.';showStorageProblem();return false;}return true;
 }catch{storageError='Хранилище недоступно. Скачайте JSON перед закрытием вкладки.';showStorageProblem();return false;}
}
function persist(invalidate=true,{recover=false}={}){
 if(invalidate)campaignCache=null;if(!canWrite({recover}))return false;
 try{const next=JSON.stringify(saved);localStorage.setItem(storageKey,next);storageSnapshot=next;storageError='';if(recover)storageCorrupt=false;document.getElementById('storage-problem-root')?.remove();return true;}
 catch{storageError='Хранилище заполнено или недоступно. Экспортируйте дела перед закрытием вкладки.';showStorageProblem();return false;}
}
function resetCorruptData(){
 if(!storageCorrupt)return;
 try{if(localStorage.getItem(storageKey)!==storageSnapshot){showStorageConflict();return;}
 localStorage.removeItem(storageKey);storageSnapshot=null;storageCorrupt=false;clearAllInputDrafts();saved=emptyLocalState();storageError='';state.recoveryMode=false;document.getElementById('storage-problem-root')?.remove();closeModal();navigate('overview');toast('Повреждённый локальный снимок удалён.');
 }catch{storageError='Не удалось очистить локальное хранилище.';showStorageProblem();}
}
function confirmCorruptReset(){
 document.getElementById('storage-problem-root')?.setAttribute('hidden','');returnFocus=document.activeElement;document.body.style.overflow='hidden';$('#modal-root').innerHTML='<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="reset-title"><div class="modal-head"><h2 id="reset-title">Начать заново?</h2></div><div class="modal-body"><p>Это удалит недоступный локальный снимок. Сначала можно скачать его: без копии восстановление не предусмотрено.</p><button class="button secondary" data-action="corrupt-export">Скачать исходный снимок</button></div><div class="modal-foot"><button class="button secondary" data-action="modal-close">Отмена</button><button class="button primary" data-action="corrupt-reset-confirm">Удалить снимок и начать заново</button></div></section></div>';$('#modal-root [data-action="modal-close"]').focus();
}
window.addEventListener('storage',event=>{if(event.storageArea===localStorage&&(event.key===storageKey||event.key===null)&&event.newValue!==storageSnapshot)showStorageConflict();});
