function hero(){
 const c=analyzeCampaign(demoCampaigns[0]), a=c.analysis;
 return `<section class="product-hero" aria-labelledby="hero-title"><div class="hero-copy"><p class="hero-eyebrow">ІЗ. Розыгрыши под контролем.</p><h1 id="hero-title">Разные посты.<br><span>Целая картина.</span></h1><p class="hero-description">Соедините публикации и скриншоты.<br>Увидьте условия, которые легко упустить.</p><div class="hero-actions"><button class="button primary" data-action="new">Начать проверку</button><button class="hero-demo" data-action="demo">Смотреть демо ${icon('play')}</button></div></div><div class="product-stage"><div class="stage-glow"></div><div class="stage-label label-left">${icon('link')}3 источника. Одно дело.</div><div class="stage-label label-right">${icon('shield')}Каждый признак — с цитатой</div><div class="product-window"><div class="window-toolbar"><div class="window-controls"><i></i><i></i><i></i></div><span>${icon('shield')} Рабочее пространство ІЗ</span><span class="window-dots">•••</span></div><div class="window-content"><div class="window-case-title"><div><span class="preview-eyebrow">КАМПАНИЯ № 017</span><h3>Картина собрана.</h3></div><span class="preview-demo-label">Демонстрация</span></div><div class="window-grid"><div class="preview-sources">${c.sources.slice(0,3).map((source,i)=>`<div class="preview-source"><span class="preview-source-icon tone-${i}">${icon(['gift','money','shuffle'][i])}</span><div><span class="preview-source-label">0${i+1} · ${['Приз','Платное участие','Случайный выбор'][i]}</span><p>${esc(source.text)}</p></div><span class="preview-tick">${icon('check')}</span></div>`).join('')}<div class="preview-source-footer">${icon('link')}Условия связаны одной кампанией</div></div><div class="preview-result"><div class="score-orbit"><svg viewBox="0 0 160 160" aria-hidden="true"><circle cx="80" cy="80" r="69"/><circle class="orbit-fill" cx="80" cy="80" r="69" stroke-dasharray="390 434"/></svg><div><strong>${a.score}</strong><span>баллов приоритета</span></div></div><span class="result-caption"><i></i>Высокий приоритет</span><p>Приз + оплата +<br>случайный выбор</p><span class="preview-human">Оценку даёт аналитик</span></div></div></div></div><div class="stage-ground"></div></div><p class="hero-footnote">Синтетический пример. Баллы показывают приоритет проверки, а не вероятность нарушения.</p><a class="explore-cue" href="#workspace">К вашему рабочему пространству ${icon('down')}</a></section>`;
}
function statCards(){const all=allCampaigns();const cards=[['layers','',all.length,'Кампаний в базе','all'],['alert','red',all.filter(c=>c.analysis.risk==='high').length,'Высокий приоритет','high'],['file','lavender',all.reduce((n,c)=>n+c.sources.length,0),'Первоисточников','all'],['circleCheck','green',all.filter(c=>statusOf(c)==='resolved').length,'Разобрано аналитиком','resolved']];return `<div class="stat-grid">${cards.map(([i,cl,n,label,filter])=>`<button class="stat-card" data-action="stat" data-filter="${filter}"><span class="stat-icon ${cl}">${icon(i)}</span><span class="stat-copy"><strong>${n}</strong><p>${label}</p></span></button>`).join('')}</div>`;}
function rows(campaigns){return campaigns.map((c,i)=>`<tr tabindex="0" role="button" data-action="analyst-open" data-id="${esc(c.id)}" aria-label="Открыть: ${esc(c.title)}"><td><div class="case-title-cell"><span class="case-icon tone-${i%4}">${icon(i%3===0?'gift':i%3===1?'layers':'flag')}</span><div><strong>${esc(c.title)}</strong><small>${esc(c.organizer)} · ${esc(c.platform)}${c.synthetic?' · ДЕМО':''}</small></div></div></td><td>${badge(c.analysis.risk)}${saved.structuredReviews[c.id]?`<small class="manual-row-label">Ручной: ${esc(riskNames[saved.structuredReviews[c.id].humanRisk]||'не указан')}${isStructuredReviewCurrent(c,saved.structuredReviews[c.id])?'':' · устарел'}</small>`:''}</td><td><span class="source-count">${icon('file')}${materialCount(c.sources.length)}</span></td><td><span class="status-label ${statusOf(c)}">${{new:'Новая',review:'На проверке',resolved:'Разобрана'}[statusOf(c)]}</span></td><td>${icon('chevron','row-arrow')}</td></tr>`).join('');}
function caseTable(campaigns){return campaigns.length?`<div class="table-wrap"><table class="case-table"><thead><tr><th>КАМПАНИЯ</th><th>АВТОПРИОРИТЕТ</th><th>ИСТОЧНИКИ</th><th>СТАТУС</th><th></th></tr></thead><tbody>${rows(campaigns)}</tbody></table></div>`:`<div class="empty-state">${icon('search')}<h3>Кампании не найдены</h3><p>Измените фильтр или поисковый запрос.</p></div>`;}
function quickForm(appendToId=null){return `<form id="quick-form" data-append-to="${esc(appendToId||'')}" class="quick-form"><label for="quick-text" class="quick-label">${appendToId?'Добавьте недостающие условия':'Текст условий'}</label><p id="quick-text-hint" class="quick-field-hint">Вставьте пост, переписку или расшифровку эфира.</p><textarea id="quick-text" name="text" maxlength="60000" aria-describedby="quick-text-hint" placeholder="Например: «Билет — 3 000 ₸, победителя выберет рандомайзер»."></textarea><div class="draft-tools"><small>Текст сохраняется в этом браузере. Файлы — до закрытия вкладки. Копия черновика дополнений включает исходное дело.</small><button type="button" class="text-button" data-action="draft-previous" hidden>Вернуть мой текст</button><button type="button" class="text-button" data-action="draft-export">Скачать черновик</button><button type="button" class="text-button" data-action="draft-clear">Очистить черновик</button></div><div class="quick-upload-row"><label id="dropzone" class="quick-upload">${icon('image')}<span>Добавить скриншот</span><input id="image-input" type="file" accept="image/png,image/jpeg,image/webp" multiple></label><span>До 3 изображений · PNG, JPG, WEBP</span></div><div class="file-list" id="file-list"></div><details class="quick-origin"><summary>Аккаунт или эфир · необязательно ${icon('down')}</summary><div class="origin-grid"><label class="field"><span>Платформа</span><select name="accountPlatform"><option value="instagram">Instagram</option><option value="tiktok">TikTok</option></select></label><label class="field"><span>Аккаунт публикации</span><input name="accountHandle" maxlength="40" placeholder="@username"></label><label class="field origin-wide"><span>Ссылка на материал или профиль</span><input name="sourceUrl" type="url" placeholder="https://…"><small>Сохраняется как источник. Содержимое по ссылке не загружается.</small></label><label class="field origin-wide"><span>Тип материала</span><select name="sourceKind"><option value="post">Публикация</option><option value="live">Текст / расшифровка эфира</option><option value="message">Переписка</option></select><small>Для эфира вставьте расшифровку или добавьте скриншот условий.</small></label></div></details><div class="form-progress" id="form-progress" role="status" aria-live="polite"></div><div class="form-error" id="form-error" role="alert"></div><button class="button primary quick-submit" type="submit" id="analyze-button">${icon('scan')}${appendToId?'Добавить и проверить':'Проверить розыгрыш'}</button><p class="quick-private">${icon('shield')}Текст и изображения обрабатываются в вашем браузере.</p><p class="quick-data-note">Перед загрузкой скройте лишние персональные данные.</p></form>`;}
function overview(){return `<div class="paper-home"><section class="paper-hero" aria-labelledby="paper-hero-title"><div class="paper-hero-copy"><h1 id="paper-hero-title">Не на удачу.<br><span class="paper-underlined">По условиям.<img src="./assets/paper/raspberry-underline.webp" alt="" aria-hidden="true"></span></h1><p class="paper-hero-description">Покажем, из чего складывается<br class="paper-desktop-break"> участие в розыгрыше.</p><div class="paper-hero-actions"><button class="button primary paper-start" data-action="quick-new">Начать разбор ${icon('arrow')}</button><button class="paper-example-link" data-action="paper-example">Посмотреть пример</button></div><div class="paper-privacy"><span class="paper-privacy-symbol"><img src="./assets/paper/asterisk.svg" width="19" height="19" alt=""></span><p>Материалы обрабатываются<br>в вашем браузере.</p></div></div><figure class="paper-hero-art"><img src="./assets/paper/hero-ticket.webp" alt="Бумажный билет со знаком вопроса на малиновом фоне. Условия важнее обещаний." width="1536" height="1920" fetchpriority="high"></figure></section><section class="paper-signals" aria-labelledby="paper-signals-title"><h2 id="paper-signals-title" class="paper-eyebrow">Что смотрим</h2><div class="paper-signal"><h3>Приз</h3><p>Какой именно приз<br>и что с ним по условиям.</p></div><div class="paper-signal"><h3>Оплата</h3><p>Нужно ли платить за участие<br>и как.</p></div><div class="paper-signal"><h3>Случайность</h3><p>Как определяется победитель<br>и что на это влияет.</p></div></section><section class="paper-facts" id="approach" aria-labelledby="paper-facts-title"><div class="paper-facts-copy"><h2 id="paper-facts-title">Сначала —<br>факты.</h2><p class="paper-facts-lead">У каждого найденного признака — конкретная фраза из ваших материалов.</p><ol class="paper-steps"><li><span>01</span><div><h3>Добавьте условия</h3><p>Текст публикации, переписку или скриншот одного розыгрыша.</p></div></li><li><span>02</span><div><h3>Посмотрите основания</h3><p>Приз, оплата и способ выбора — с точными цитатами.</p></div></li><li><span>03</span><div><h3>Уточните недостающее</h3><p>Если условий не хватает, добавьте остальные материалы.</p></div></li></ol><button class="paper-text-link" data-action="paper-example">Открыть пример разбора ${icon('arrow')}</button></div><figure class="paper-facts-art"><img src="./assets/paper/facts-paper.webp" alt="Лист с условиями розыгрыша, выделениями и малиновыми пометками." width="1536" height="1024" loading="lazy"></figure></section><aside class="paper-limits"><span class="paper-eyebrow">Важная деталь</span><p>ІЗ разбирает загруженные условия. Результат не доказывает мошенничество и не гарантирует безопасность.</p><button class="paper-text-link" data-action="nav" data-route="about">О возможностях и границах ${icon('arrow')}</button></aside></div>`;}

function checkPage(){return `<section class="quick-home paper-checker"><div class="paper-check-intro"><span class="paper-eyebrow">Ваш разбор · 01 / Материалы</span><h1>Посмотрим<br>на условия.</h1><p>Добавьте то, что вам предлагают. Найденные признаки покажем вместе с цитатами.</p><div class="paper-check-note">${icon('file')}<p>Текст, скриншоты и условия из эфира — материалы одного розыгрыша.</p></div><button class="paper-text-link" data-action="paper-example">Сначала посмотреть пример ${icon('arrow')}</button></div><div class="paper-check-form">${quickForm()}<div class="quick-examples"><span>Подставить пример</span><button data-action="quick-example" data-example="paid">Платный розыгрыш ${icon('arrow')}</button><button data-action="quick-example" data-example="free">Бесплатный конкурс ${icon('arrow')}</button><button data-action="network-demo">Серия розыгрышей ${icon('arrow')}</button></div><p class="quick-scope">Нужен текст предложения или скриншот. По одной ссылке на профиль проверка не работает.</p></div></section>`;}

function consumerResult(){
 const c=campaignById(state.selectedId);if(!c)return overview();
 const a=c.analysis,v=consumerVerdict(c),moneyKey=a.signals.income.state==='found'?'income':'collection';
 const items=[['prize','Обещают приз','Не указано, что разыгрывают'],['payment','Требуют оплату за участие','Обязательная оплата не найдена в тексте'],['random','Победителя выбирают случайно','Не найдено явного случайного выбора'],[moneyKey,moneyKey==='income'?'Заявлен доход или комиссия организатора':'Указан сбор денег или продажа мест; прибыль не подтверждена','Сбор денег и доход организатора не подтверждены']];
 return `<section class="consumer-result"><button class="back-button" data-action="quick-new">${icon('back')}Проверить другой розыгрыш</button><div class="verdict-hero ${v.tone}"><div class="verdict-symbol">${icon(v.icon)}</div><span class="verdict-label">${esc(v.label)}</span><h1>${esc(v.title)}</h1><p>${esc(v.description)}</p>${c.synthetic?'<span class="consumer-demo-tag">Демонстрационный пример</span>':c.containsSyntheticSources?'<span class="consumer-demo-tag">Есть синтетические источники</span>':''}</div><section class="plain-reasons"><h2>Что видно в условиях</h2>${items.map(([key,yes,no])=>{const signal=a.signals[key],found=signal.state==='found',conflict=signal.state==='conflict',e=signal.evidence[0];return `<article class="plain-reason ${found?'found':'unknown'}"><span class="plain-reason-icon">${icon(found?'check':'minus')}</span><div><h3>${esc(conflict?'Условия выбора противоречат друг другу':found?yes:no)}</h3>${e?`<blockquote>${esc(e.quote)}</blockquote>`:''}</div></article>`;}).join('')}${a.signals.free.state!=='unknown'?`<article class="plain-reason found free-reason"><span class="plain-reason-icon">${icon('check')}</span><div><h3>${a.signals.free.state==='conflict'?'Одновременно обещают бесплатное участие':'В тексте заявлено бесплатное участие'}</h3><blockquote>${esc(a.signals.free.evidence[0]?.quote||'')}</blockquote></div></article>`:''}</section>${relationsPanel(c)}<section class="next-steps ${v.tone}"><h2>${esc(v.actionTitle)}</h2><ul>${v.actions.map(t=>`<li>${icon('chevron')}<span>${esc(t)}</span></li>`).join('')}</ul></section><p class="consumer-limit">Этот результат не доказывает мошенничество и не гарантирует безопасность. ІЗ анализирует загруженные условия, а не проверяет сам аккаунт.</p>${saved.campaigns.some(x=>x.id===c.id)?`<div class="consumer-result-actions"><button class="button primary" data-action="quick-append">${icon('plus')}Добавить условия</button><button class="button secondary" data-action="quick-new">Проверить другой</button></div>${state.quickAppendOpen?`<section class="quick-append-section" id="quick-append">${quickForm(c.id)}</section>`:''}`:`<div class="consumer-result-actions"><button class="button primary" data-action="quick-new">Проверить свой розыгрыш</button></div>`}<details class="consumer-materials"><summary>Исходные материалы <span>${c.sources.length}</span>${icon('down')}</summary><div>${c.sources.map((source,i)=>`<article class="plain-material"><h3>Материал ${i+1}${source.type==='image'?' · скриншот':source.kind==='live'?' · текст эфира':''}</h3>${normalizeAccount(source.account,source.url,c.synthetic)?`<small>Указанный аккаунт: ${esc(normalizeAccount(source.account,source.url,c.synthetic).label)}</small>`:''}${safeImage(source.image)?`<img src="${esc(safeImage(source.image))}" alt="Загруженный скриншот">`:''}<p>${esc(source.text)}</p>${source.ocrConfidence!=null?'<small>Текст распознан автоматически. Сверьте его с изображением.</small>':''}</article>`).join('')}</div><button class="text-button" data-action="quick-expert">Открыть подробный разбор ${icon('chevron')}</button>${saved.campaigns.some(x=>x.id===c.id)?'<button class="text-button delete-case-link" data-action="delete-case">Удалить проверку</button>':''}</details></section>`;
}
function relationsPanel(c){
 const r=campaignRelations(c,allCampaigns());
 return `<details class="account-relations" ${r.related.length||r.multipleAccounts?'open':''}><summary>${icon('graph')}Связи и повторения <span>${r.related.length?'совпадений: '+r.related.length:r.accounts.length?'аккаунт указан':'укажите профиль организатора'}</span>${icon('down')}</summary><div class="relations-body">${r.accounts.length?`<div class="account-node-row">${r.accounts.map(a=>`<span class="account-node">${icon('globe')}${esc(a.label)}</span>`).join('')}</div><p class="relations-caption">${r.multipleAccounts?'В этой проверке объединены материалы нескольких указанных аккаунтов. Принадлежность одному розыгрышу нужно сверить по источникам.':'Совпадения ищутся в других проверках, сохранённых в этом браузере.'}</p>`:'<p class="relations-caption">Чтобы увидеть повторяемость, укажите платформу и профиль организатора при добавлении материала. Вход через Google для этого не нужен.</p>'}${r.related.map(other=>`<button class="related-case" data-action="open" data-id="${esc(other.id)}"><span>${icon('link')}<strong>${esc(other.title)}</strong><small>${esc(other.series?'Разные ID розыгрышей у одного аккаунта':'Ещё одна проверка с этим аккаунтом')}: ${esc(other.accounts.join(', '))}</small>${other.references.length?`<small>${esc(other.references.join(' · '))}</small>`:''}</span>${icon('chevron')}</button>`).join('')}${r.accounts.length&&!r.related.length?'<p class="relations-empty">Других проверок с этим аккаунтом пока нет. Отсутствие совпадений не доказывает отсутствие серии.</p>':''}<p class="relations-limit">${esc(r.limitation)}</p></div></details>`;
}
function consumerHistoryItems(){const query=state.query.toLocaleLowerCase();const list=saved.campaigns.map(c=>analyzeCampaign(c)).filter(c=>c.title.toLocaleLowerCase().includes(query));return list.length?list.map(c=>{const v=consumerVerdict(c);return `<button class="consumer-history-card" data-action="open" data-id="${esc(c.id)}"><span class="history-symbol ${v.tone}">${icon(v.icon)}</span><span class="history-copy"><strong>${esc(c.title)}</strong><span>${esc(v.short)}</span><small>${materialCount(c.sources.length)}${c.synthetic?' · пример':''}</small></span>${icon('chevron')}</button>`;}).join(''):'<div class="empty-state"><h3>Проверки не найдены</h3><p>Измените поисковый запрос.</p></div>';}
function consumerHistory(){return `<section class="consumer-history"><div class="simple-page-title"><div><h1>Мои проверки</h1><p>Сохраняются в этом браузере.</p></div><button class="button primary" data-action="quick-new">${icon('plus')}Новая проверка</button></div>${saved.campaigns.length?`<label class="search-box consumer-search">${icon('search')}<input id="consumer-search" type="search" aria-label="Найти проверку" placeholder="Найти проверку…" value="${esc(state.query)}"></label><div class="consumer-history-list" id="consumer-history-list">${consumerHistoryItems()}</div>`:`<div class="empty-state">${icon('clock')}<h2>Здесь будут ваши проверки</h2><p>Добавьте текст или скриншот розыгрыша.</p><button class="button primary" data-action="quick-new">Проверить розыгрыш</button></div>`}<div class="history-tools"><button class="text-button" data-action="quick-import">Импорт проверок</button>${saved.campaigns.length?'<button class="text-button" data-action="quick-export-all">Скачать мои проверки</button><button class="text-button" data-action="delete-all">Удалить мои проверки</button>':''}</div></section>`;}
function consumerAbout(){return `<section class="consumer-about"><button class="back-button" data-action="quick-new">${icon('back')}К проверке</button><h1>Простая проверка<br>условий розыгрыша.</h1><div class="about-step"><span>1</span><div><h2>Добавьте предложение</h2><p>Вставьте текст поста или переписки, загрузите скриншот. Можно добавить несколько материалов одного розыгрыша, включая текст эфира. Если указан аккаунт, ІЗ сопоставит его с другими загруженными проверками.</p></div></div><div class="about-step"><span>2</span><div><h2>Посмотрите, что настораживает</h2><p>ІЗ ищет приз, обязательную оплату участия, случайный выбор и сведения о сборе денег или комиссии организатора. Сбор денег сам по себе не доказывает прибыль. Найденные фразы показываются рядом с результатом.</p></div></div><div class="about-step"><span>3</span><div><h2>Уточните недостающее</h2><p>Если данных мало или условия противоречат друг другу, добавьте остальные сообщения. Отсутствие найденных признаков не означает, что предложение безопасно.</p></div></div><div class="about-limits"><h2>Границы проверки</h2><p>Это прототип для анализа условий розыгрышей. Связи строятся только по указанным аккаунтам и ID в загруженных материалах. Он не проверяет подлинность аккаунта, не открывает посты по ссылке и не устанавливает факт мошенничества. Распознавание изображений и правила анализа могут ошибаться.</p><p>Материалы хранятся в браузере. Очистка данных сайта удалит их; нужные проверки можно скачать.</p><button class="text-button" data-action="nav" data-route="method">Методика для специалистов ${icon('chevron')}</button></div><button class="button primary" data-action="quick-new">Проверить розыгрыш</button></section>`;}
async function submitQuick(event){
 event.preventDefault();if(state.busy)return;
 const form=event.target,data=new FormData(form),text=String(data.get('text')||'').trim();
 const targetId=form.dataset.appendTo,existing=targetId?saved.campaigns.find(c=>c.id===targetId):null;
 $('#form-error')?.classList.remove('visible');
 try{
  if(!canWrite())throw new Error(storageError);
  if(targetId&&!existing)throw new Error('Проверка не найдена. Откройте её из истории.');
  if(!text&&!state.files.length)throw new Error('Вставьте текст предложения или добавьте скриншот.');
  if(/^https?:\/\/\S+$/iu.test(text)&&!state.files.length)throw new Error('По одной ссылке нельзя прочитать условия. Вставьте текст поста или загрузите скриншот.');
  if((existing?.sources.length||0)+(text?1:0)+state.files.length>50)throw new Error('В одной проверке можно хранить до 50 материалов.');
  const sourceUrl=safeUrl(data.get('sourceUrl'));
  const typedHandle=String(data.get('accountHandle')||'').trim();
  const typedAccount=normalizeAccount({platform:data.get('accountPlatform'),handle:typedHandle});
  if(typedHandle&&!typedAccount)throw new Error('Укажите имя аккаунта без пробелов: например @username.');
  const linkedAccount=normalizeAccount(null,sourceUrl);
  if(typedAccount&&linkedAccount&&typedAccount.key!==linkedAccount.key)throw new Error('Указанный аккаунт и аккаунт в ссылке различаются. Проверьте источник.');
  const account=typedAccount||linkedAccount,kind=['post','live','message'].includes(data.get('sourceKind'))?data.get('sourceKind'):'post';
  state.busy=true;document.querySelectorAll('button,input,textarea,select').forEach(el=>{el.disabled=true;});
  progress(state.files.length?'Читаем текст со скриншота…':'Читаем условия…');
  const images=await recognizeImages(state.files), id=existing?.id||'case-'+crypto.randomUUID(),now=new Date().toISOString();
  const sources=[...(text?[{type:'text',text}]:[]),...images].map(item=>({...item,synthetic:item.type==='text'&&Object.values(quickExamples).includes(item.text),id:'source-'+crypto.randomUUID(),author:account?.label||'Добавлено пользователем',account,kind,url:sourceUrl,timestamp:now,campaignRef:id}));
  if(existing){appendCampaignSources(existing,sources,now);}
  else saved.campaigns.unshift({id,title:text?text.replace(/\s+/gu,' ').slice(0,70)+(text.length>70?'…':''):'Розыгрыш со скриншота',organizer:account?.label||'Не указан',platform:account?.platform==='instagram'?'Instagram':account?.platform==='tiktok'?'TikTok':images.length?'Скриншоты / текст':'Текст предложения',status:'new',synthetic:!images.length&&Object.values(quickExamples).includes(text),containsSyntheticSources:sources.some(s=>s.synthetic===true)&&!(!images.length&&Object.values(quickExamples).includes(text)),manualGrouping:true,createdAt:now,sources});
  const stored=persist();if(stored)completeInputDraft(form);state.busy=false;rememberInputDraft();state.files=[];openCase(id);
  if(!stored)toast('Хранилище заполнено. Скачайте проверку в подробном разборе, чтобы сохранить материалы.');
 }catch(error){state.busy=false;document.querySelectorAll('button,input,textarea,select').forEach(el=>{el.disabled=false;});$('#form-progress')?.classList.remove('visible');showError(error.message||'Не удалось прочитать условия. Попробуйте ещё раз.');}
}
function filtered(){return queueCampaigns(allCampaigns(),saved.reviews,{filter:state.filter,scope:state.scope,query:state.query,structuredReviews:saved.structuredReviews});}
function campaignsPage(){const all=allCampaigns(),stats=reviewSummary(all,saved.reviews,saved.structuredReviews);return '<section class="workspace-view paper-workspace">'+heading('Рабочее место аналитика','Сначала незавершённые проверки высокого приоритета. Синтетические примеры помечены ДЕМО.',`<button class="button secondary" data-action="nav" data-route="network">${icon('graph')}Сеть связей</button><button class="button secondary" data-action="quick-import">${icon('upload')}Импорт</button><button class="button secondary" data-action="export-all">${icon('download')}Экспорт</button>${newButton()}`)+`<div class="analyst-guide"><ol aria-label="Порядок проверки"><li><span>01</span>Добавьте материалы</li><li><span>02</span>Проверьте цитаты</li><li><span>03</span>Сохраните решение</li></ol><button class="paper-text-link" data-action="nav" data-route="method">Метрики и методика ${icon('arrow')}</button></div><div class="queue-summary"><div><strong>${stats.pending}</strong><span>В очереди</span></div><div><strong>${stats.resolved}</strong><span>Разобрано</span></div><div><strong>${stats.medianSeconds===null?'—':stats.medianSeconds+' с'}</strong><span>Медиана сессии<small>${stats.timed} замеров</small></span></div><p>Статистика — по вашим материалам. Время считается при открытом разборе в видимой вкладке до сохранения решения. Сравнение с работой без ІЗ не проводилось.</p></div><section class="panel paper-queue-panel" aria-label="Очередь проверок"><div class="scope-tabs"><button class="text-button ${state.scope==='all'?'active':''}" data-action="scope" data-scope="all" aria-pressed="${state.scope==='all'}">Все и демо</button><button class="text-button ${state.scope==='own'?'active':''}" data-action="scope" data-scope="own" aria-pressed="${state.scope==='own'}">Только мои материалы</button></div><div class="filters"><div class="filter-tabs" role="group" aria-label="Фильтр приоритета">${[['all','Все'],['pending','К проверке'],['high','Высокий'],['medium','Средний'],['low','Низкий'],['resolved','Разобраны']].map(([key,label])=>`<button class="filter-tab ${state.filter===key?'active':''}" data-action="filter" data-filter="${key}" aria-pressed="${state.filter===key}">${label}<span>${queueCampaigns(all,saved.reviews,{filter:key,scope:state.scope,structuredReviews:saved.structuredReviews}).length}</span></button>`).join('')}</div><label class="search-box">${icon('search')}<input id="case-search" type="search" aria-label="Поиск кампаний" placeholder="Найти кампанию…" value="${esc(state.query)}"></label></div><div id="campaign-table">${caseTable(filtered())}</div></section>`+'</section>';}
function signalEvidence(c,key){return c.analysis.signals[key]?.evidence||[];}
function highlighted(text,c,sourceId){const intervals=[];for(const key of ['prize','payment','random','collection','income','free','warning']) for(const e of signalEvidence(c,key)) if(e.sourceId===sourceId && e.end>e.start) intervals.push([e.start,e.end]);intervals.sort((a,b)=>a[0]-b[0]);const merged=[];for(const i of intervals){const last=merged.at(-1);if(last&&i[0]<=last[1])last[1]=Math.max(last[1],i[1]);else merged.push([...i]);}let cursor=0;let result='';for(const [start,end]of merged){result+=esc(text.slice(cursor,start))+`<mark>${esc(text.slice(start,end))}</mark>`;cursor=end;}return result+esc(text.slice(cursor));}
function sourceCard(source,c,index){const keys=Object.keys(c.analysis.signals).filter(k=>signalEvidence(c,k).some(e=>e.sourceId===source.id));const img=safeImage(source.image);return `<article class="source-card ${state.activeSource===source.id?'active-source':''}" id="source-${esc(source.id)}"><div class="source-card-header"><div class="source-person"><span class="case-icon tone-${index%4}">${icon(source.type==='image'?'image':'file')}</span><div><strong>${esc(source.author||c.organizer)}</strong><small>${esc(source.date||formatTime(source.timestamp))} · Источник ${index+1}</small></div></div><span class="source-tag">${icon(source.type==='image'?'scan':'file')}${source.type==='image'?'Текст изображения':source.kind==='live'?'Текст эфира':'Публикация'}</span></div>${img?`<img class="source-image" src="${esc(img)}" alt="${source.ocrConfidence?'Загруженное изображение':'Синтетический скриншот условий розыгрыша'}" loading="lazy">`:''}<p class="source-text">${highlighted(source.text,c,source.id)}</p><div class="source-bottom">${keys.map(k=>`<span class="evidence-chip">${icon(signalIcons[k])}${signalNames[k]}</span>`).join('')}${!keys.length?'<span>Явные признаки не найдены</span>':''}<span style="margin-left:auto">${c.synthetic||source.synthetic?'Синтетический источник':'Добавлено пользователем'}</span>${!c.synthetic?`<button class="text-button" data-action="edit-source" data-source="${esc(source.id)}">${icon('edit')}Исправить текст</button>`:''}</div>${source.ocrConfidence!=null?`<div class="evidence-note">Текст распознан автоматически. Качество OCR: ${Math.round(source.ocrConfidence)} / 100 — характеристика распознавания, а не достоверности публикации. Проверьте текст по изображению.</div>`:''}${source.url&&safeUrl(source.url)?`<div class="evidence-note">${icon('link')} ${c.synthetic?'Пример ссылки на первоисточник:':'Указанный первоисточник:'} <a href="${esc(safeUrl(source.url))}" target="_blank" rel="noopener noreferrer">${esc(source.url.replace(/^https?:\/\//,''))}</a></div>`:''}</article>`;}
function graphView(c){const sources=c.sources.slice(0,8);const height=Math.max(310,sources.length*90);const centerY=height/2;return `<section class="graph-panel"><svg viewBox="0 0 730 ${height}" role="img" aria-label="Связи источников кампании"><defs><pattern id="dots" width="17" height="17" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r=".7" fill="#d5cbbb"/></pattern></defs><rect width="730" height="${height}" fill="url(#dots)" rx="8"/>${sources.map((s,i)=>{const y=35+i*90;return `<path d="M265 ${centerY} C360 ${centerY} 350 ${y+29} 448 ${y+29}" stroke="#ba9eaa" stroke-width="1.5" fill="none"/><circle cx="448" cy="${y+29}" r="3" fill="#aa1749"/>`;}).join('')}<rect x="35" y="${centerY-47}" width="230" height="94" rx="14" fill="#111111"/><text x="55" y="${centerY-17}" fill="#f5f0e6" font-family="sans-serif" font-size="10">ОДНА КАМПАНИЯ</text><text x="55" y="${centerY+7}" fill="white" font-family="sans-serif" font-size="12" font-weight="bold">${esc(c.title.length>26?c.title.slice(0,26)+'…':c.title)}</text><text x="55" y="${centerY+29}" fill="#f5f0e6" font-family="sans-serif" font-size="9">${esc(c.manualGrouping?'Материалы сгруппированы вручную':c.groupingNotes?'Связаны явными ссылками':c.id)}</text>${sources.map((s,i)=>{const y=35+i*90;const keys=['prize','payment','random','collection','income','free','warning'].filter(k=>signalEvidence(c,k).some(e=>e.sourceId===s.id));return `<g class="graph-source"><rect x="448" y="${y}" width="254" height="60" rx="9" fill="#fff" stroke="#c9c2b7"/><text x="465" y="${y+23}" fill="#111111" font-family="sans-serif" font-size="11">Источник ${i+1} · ${s.type==='image'?'скриншот':s.kind==='live'?'текст эфира':'публикация'}</text><text x="465" y="${y+43}" fill="#625a50" font-family="sans-serif" font-size="9">${esc(keys.map(k=>signalNames[k]).join(' · ')||'Дополнительный контекст')}</text></g>`;}).join('')}</svg><p class="graph-scope">Схема показывает ${sources.length} из ${c.sources.length} материалов. Откройте любой источник кнопкой ниже.</p><ul class="graph-source-list" aria-label="Все источники кампании">${c.sources.map((s,i)=>`<li><button data-action="focus-source" data-source="${esc(s.id)}" aria-label="Показать источник ${i+1}"><span>Источник ${i+1} · ${s.type==='image'?'скриншот':s.kind==='live'?'текст эфира':'публикация'}</span>${icon('arrow')}</button></li>`).join('')}</ul><div class="graph-legend"><span><i></i>Материал кампании</span><span>${icon('file')}Кнопки открывают исходный материал</span></div><div class="evidence-note">${c.manualGrouping?'Вы добавили эти материалы в одну проверку. Такая группировка не подтверждает принадлежность одному организатору.':c.groupingNotes?c.groupingNotes.map(esc).join(' · '):`Связь задана точным идентификатором кампании: ${esc(c.id)}. Сходство оформления или общий домен не являются подтверждением связи.`}</div></section>`;}
function decisionPanel(c){
  const a=c.analysis, review=normalizeReview(saved.reviews[c.id]), current=isReviewCurrent(c,review);
  const entry=r=>`<li><strong>${esc(decisionLabels[r.decision])}</strong><small>${esc(formatTime(r.at))} · ${r.sourceCount??'?'} материалов · ${esc(r.engineVersion||'версия не записана')}</small>${r.note?`<p>${esc(r.note)}</p>`:''}</li>`;
  return `<aside class="decision-panel"><h3>Автоматический приоритет</h3>${badge(a.risk)}<p class="priority-explanation">${a.risk==='high'?'Сверьте три основания по полным условиям.':a.risk==='medium'?'Уточните недостающие или противоречивые условия.':'Отсутствие явных признаков не подтверждает безопасность.'}</p><details class="priority-scale"><summary>Как рассчитан приоритет</summary><p>Служебная шкала правил: ${a.score} из 100. Это не вероятность нарушения, мошенничества или точности ответа.</p></details><div class="decision-divider"></div><div class="eyebrow">Почему этот приоритет</div><ul class="reasons">${a.reasons.map(r=>`<li>${icon('check')}<span>${esc(r)}</span></li>`).join('')}</ul>${a.missing.length?`<div class="eyebrow" style="margin-top:18px">Чего не хватает</div><ul class="reasons missing">${a.missing.map(r=>`<li>${icon('minus')}<span>${esc(r)}</span></li>`).join('')}</ul>`:''}<div class="decision-divider"></div><h3 style="margin-bottom:10px">Заметка к проверке</h3><p class="score-caption">Итоговый разбор сохраняется после проверки трёх признаков. Заметка помогает вернуться к недостающим условиям.</p><p class="review-time">Эта сессия: <span id="review-clock">0:00</span> · только видимая вкладка</p>${review?`<div class="review-result ${current?'':'stale'}">${current?'Прежняя быстрая пометка · полный разбор не сохранён':'Нужна повторная проверка'}<strong>${esc(decisionLabels[review.decision])}</strong><small>${esc(formatTime(review.at))}</small>${review.note?`<p>${esc(review.note)}</p>`:''}${!current?'<small>Материалы или правила изменились, либо у старого решения нет отметки версии.</small>':''}</div>`:'<p class="score-caption">Сверьте условия по первоисточникам и сохраните своё решение.</p>'}${state.demoStep!==null?'<p class="evidence-note">Завершите пошаговую демонстрацию перед сохранением решения.</p>':`<label class="field review-note"><span>Комментарий к новому решению</span><textarea id="review-note" maxlength="2000" rows="3" placeholder="Что проверено и что нужно уточнить…">${esc(reviewDrafts.get(c.id)||'')}</textarea></label><div class="review-buttons"><button class="button secondary" data-action="review" data-decision="later">${icon('clock')}Сохранить заметку и отложить</button></div>`}<button class="button secondary queue-next" data-action="queue-next">Следующая в очереди ${icon('arrow')}</button>${review?.history.length?`<details class="review-history"><summary>История решений · ${review.history.length}</summary><ol>${review.history.slice().reverse().map(entry).join('')}</ol><small>Последние 100 решений. История хранится локально.</small></details>`:''}</aside>`;
}
function detail(){let full=campaignById(state.selectedId);if(!full){state.selectedId=null;return campaignsPage();}let c=state.demoStep!==null?analyzeCampaign({...full,sources:full.sources.slice(0,state.demoStep)}):full;const a=c.analysis;const sourceCount=full.sources.length;return `<section class="workspace-view paper-case"><button class="back-button" data-action="back">${icon('back')}К списку кампаний</button>`+heading(esc(c.title),'',`${saved.campaigns.some(v=>v.id===c.id)?`<button class="button primary" data-action="append-material">${icon('plus')}Добавить материал</button>`:''}<button class="button secondary" data-action="case-report">${icon('file')}Отчёт</button><button class="button secondary" data-action="export-case">${icon('download')}JSON</button>${saved.campaigns.some(x=>x.id===c.id)?'<button class="text-button" data-action="delete-case">Удалить</button>':''}`)+`<div class="detail-meta"><span>${icon('globe')}${esc(c.platform)}</span><span>${icon('layers')}${esc(c.organizer)}</span><span>${icon('file')}${c.sources.length} из ${sourceCount} материалов</span><span class="dataset-tag">${c.synthetic?'Синтетическая кампания':c.containsSyntheticSources?'Локальная проверка · есть примеры':'Локальная проверка'}</span></div>${state.demoStep!==null?`<div class="demo-banner"><div><h3>Демонстрация · шаг ${state.demoStep} из ${sourceCount}</h3><p>${state.demoStep===1?'Есть объявление о призе. Что изменится, когда появятся условия?':state.demoStep<sourceCount?'Появились новые условия. Добавим следующий источник.':'Условия собраны. Сравним с похожим бесплатным розыгрышем.'}</p></div><button class="button" data-action="demo-next">${state.demoStep<sourceCount?'Добавить следующий источник':'Сравнить с бесплатным'}${icon('arrow')}</button><button class="icon-button" data-action="demo-exit" aria-label="Выйти из демонстрации">${icon('close')}</button></div>`:''}<div class="detail-layout"><div><section class="evidence-summary"><div class="summary-top"><h2>Картина по условиям</h2><span class="dataset-tag">${['prize','payment','random'].filter(k=>a.signals[k].state==='found').length} из 3 ключевых признаков</span></div><p>${esc(a.risk==='high'?'Найдены приз, обязательная оплата участия и случайный выбор победителя.':a.summary)}</p><p class="case-priority-line">Автоматический приоритет ${badge(a.risk)}</p><div class="signal-grid">${['prize','payment','random','income'].map(k=>{const s=a.signals[k];return `<button class="signal-item ${s.state}" data-action="signal" data-signal="${k}">${icon(signalIcons[k])}<strong>${signalNames[k]}</strong><small>${s.state==='found'?'Есть указание':s.state==='conflict'?'Есть противоречие':'Недостаточно данных'}</small></button>`;}).join('')}</div></section>${a.contradictions.map(t=>`<div class="contradiction">${icon('alert')} ${esc(t)}</div>`).join('')}${originalReferenceConflict(c).conflict?'<section class="contradiction"><strong>В деле разные исходные ID розыгрышей.</strong><p>Суммарные условия нельзя считать условиями одного розыгрыша. Создайте раздельные копии по ID; исходное дело и его решения сохранятся.</p><button class="button secondary" data-action="split-original">Создать раздельные копии</button></section>':''}${contextView(c)}${sourceSensitivityView(c,sensitivityFor(c))}<div class="detail-tabs" role="tablist"><button class="detail-tab ${state.detailsTab==='sources'?'active':''}" data-action="detail-tab" data-tab="sources" role="tab" aria-selected="${state.detailsTab==='sources'}">${icon('file')}Первоисточники<span>${c.sources.length}</span></button><button class="detail-tab ${state.detailsTab==='graph'?'active':''}" data-action="detail-tab" data-tab="graph" role="tab" aria-selected="${state.detailsTab==='graph'}">${icon('graph')}Карта связей</button></div>${state.detailsTab==='sources'?c.sources.map((s,i)=>sourceCard(s,c,i)).join(''):graphView(c)}${relationsPanel(c)}${state.demoStep===null?structuredReviewPanel(c,saved.structuredDrafts[c.id],saved.structuredReviews[c.id]):''}</div>${decisionPanel(c)}</div></section>`;}
const pct=n=>`${Math.round(n*100)}%`;
function networkForCase(c){try{const n=buildNetwork(allCampaigns()),nodes=new Map(n.nodes.map(x=>[x.id,x])),id=n.nodes.find(x=>x.kind==='campaign'&&x.campaignId===networkMaterialKey(c.id))?.id;return {notice:'Точное совпадение — только кандидат связи, без вывода об общем владельце или нарушении.',candidates:n.candidates.filter(x=>x.campaignIds.includes(id)).map(x=>({label:x.label,accounts:x.accountIds.map(a=>nodes.get(a)?.label||''),evidence:x.evidence}))};}catch{return null;}}
