function progress(message){const el=$('#form-progress');if(el){el.textContent=message;el.classList.add('visible');}}
function filesUI(){const el=$('#file-list');if(el)el.innerHTML=state.files.map((f,i)=>`<div class="file-item">${icon(f.type==='application/json'?'file':'image')}<span>${esc(f.name)} · ${(f.size/1024).toFixed(0)} КБ</span><button type="button" data-action="remove-file" data-index="${i}" aria-label="Убрать ${esc(f.name)}">${icon('close')}</button></div>`).join('');}
function acceptFiles(files){if(state.busy)return;const images=Array.from(files).filter(f=>['image/png','image/jpeg','image/webp'].includes(f.type));if(images.length!==files.length){showError('Выберите PNG, JPG или WEBP. Другие форматы не поддерживаются.');return;}if(images.some(f=>f.size>5*1024*1024)){showError('Изображение должно быть меньше 5 МБ.');return;}if(state.files.length+images.length>3){showError('Для одной проверки можно добавить до 3 изображений.');return;}try{const next=[...state.files,...images],key=draftKey(visibleInputForm());if(key)inputDrafts.setFiles(key,next);state.files=next;filesUI();}catch(error){showError(error.message);}}
async function resizeImage(file){const bmp=await createImageBitmap(file);const ratio=Math.min(1,1800/Math.max(bmp.width,bmp.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bmp.width*ratio);canvas.height=Math.round(bmp.height*ratio);canvas.getContext('2d').drawImage(bmp,0,0,canvas.width,canvas.height);bmp.close();return canvas.toDataURL('image/jpeg',.88);}
