if(existing){appendCampaignSources(existing,sources);}
else saved.campaigns.unshift({id,title:String(data.get('title')).trim(),organizer:String(data.get('organizer')||'Не указан').trim(),platform:images.length?'Скриншоты / текст':'Ручной ввод',status:'new',synthetic:false,manualGrouping:true,createdAt:new Date().toISOString(),sources});
