function editSource(sourceId){const c=saved.campaigns.find(c=>c.id===state.selectedId);const s=c?.sources.find(s=>s.id===sourceId);if(!s)return;state.editSourceId=sourceId;returnFocus=document.activeElement;document.body.style.overflow='hidden';$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">Проверить текст источника</h2><p>Исправьте распознавание по изображению. Оценка будет пересчитана.</p></div><button class="icon-button" data-action="modal-close" aria-label="Закрыть">${icon('close')}</button></div><form id="edit-form"><div class="modal-body">${safeImage(s.image)?`<img class="source-image" src="${esc(s.image)}" alt="Исходное изображение">`:''}<label class="field"><span>Текст публикации</span><textarea name="text" required maxlength="60000" class="form-textarea">${esc(s.text)}</textarea></label><div class="form-error" id="form-error" role="alert"></div></div><div class="modal-foot"><small>Исходный текст сохраняется в истории материала.</small><div><button type="button" class="button secondary" data-action="modal-close">Отмена</button><button type="submit" class="button primary">Сохранить исправление</button></div></div></form></section></div>`;$('#edit-form textarea').focus();}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el){if(event.target.classList.contains('modal-overlay'))closeModal();return;}const a=el.dataset.action;if(el.tagName==='A')event.preventDefault();if(a==='corrupt-export'){download('iz-damaged-local-data.json',storageSnapshot||'','application/json;charset=utf-8');return;}if(a==='corrupt-import'){openModal('json',null,true);return;}if(a==='corrupt-reset'){confirmCorruptReset();return;}if(a==='corrupt-reset-confirm'){resetCorruptData();return;}if(a==='cancel-import'){importController?.abort();return;}if(a==='conflict-export'){saveBackup('iz-unsaved-tab-snapshot.json',allCampaigns());return;}if(a==='conflict-reload'){location.reload();return;}if(state.busy)return;switch(a){case'auth-open':showAuthDialog();break;case'auth-sign-out':signOutGoogle();closeModal();render();toast('Вы вышли из аккаунта. Проверки остались в этом браузере.');break;case'nav':navigate(el.dataset.route);break;case'new':case'quick-new':state.query='';navigate('check');break;case'paper-example':openCase(demoCampaigns[0].id);break;case'paper-approach':{const menu=document.getElementById('paper-mobile-menu'),toggle=document.querySelector('.paper-menu-toggle');if(menu)menu.hidden=true;toggle?.setAttribute('aria-expanded','false');toggle?.setAttribute('aria-label','Открыть меню');if(state.selectedId||state.route!=='overview')navigate('overview');requestAnimationFrame(()=>{const section=document.getElementById('approach');if(section){section.setAttribute('tabindex','-1');section.focus({preventScroll:true});section.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}});break;}case'paper-menu':{const menu=document.getElementById('paper-mobile-menu'),open=el.getAttribute('aria-expanded')==='true';el.setAttribute('aria-expanded',String(!open));el.setAttribute('aria-label',open?'Открыть меню':'Закрыть меню');if(menu)menu.hidden=open;break;}case'network-demo':state.scope='all';navigate('network');break;case'network-source':openCase(el.dataset.id,false,true);focusSource(el.dataset.source);break;case'export-network':{try{download('iz-network.json',buildNetwork(allCampaigns().filter(c=>state.scope!=='own'||!c.synthetic)));}catch(e){toast(e.message);}break;}case'quick-example':{if(!$('#quick-form'))navigate('check');const form=$('#quick-form'),key=draftKey(form);if(form&&key){try{inputDrafts.useExample(form,key,quickExamples[el.dataset.example]||'');syncDraftTools();$('#quick-text').focus();}catch(error){toast(error.message);}}break;}case'draft-previous':{const form=visibleInputForm(),key=draftKey(form);if(key)inputDrafts.restorePrevious(form,key);syncDraftTools();break;}case'draft-export':{rememberInputDraft();try{download('iz-input-drafts-backup.json',createDraftBackup(saved.campaigns.map(exportCampaign),inputDrafts.snapshot()));toast('Скачаны черновики и связанные исходные дела для восстановления.');}catch(error){toast(error.message);}break;}case'draft-clear':{const form=visibleInputForm(),key=draftKey(form);if(key){inputDrafts.clear(key);form.reset();state.files=[];filesUI();syncDraftTools();}break;}case'quick-append':rememberInputDraft();state.quickAppendOpen=true;state.files=[];render();$('#quick-append')?.scrollIntoView({behavior:'smooth',block:'center'});$('#quick-text')?.focus({preventScroll:true});break;case'quick-expert':rememberInputDraft();state.quickAppendOpen=false;state.files=[];state.expert=true;clockStart(state.selectedId);state.demoStep=null;render();window.scrollTo({top:0});break;case'quick-import':openModal('json');break;case'delete-case':requestDeletion(state.selectedId);break;case'delete-all':requestDeletion();break;case'delete-confirm':confirmDeletion();break;case'delete-backup':{const list=deletionTarget==='all'?allCampaigns():saved.campaigns.filter(c=>c.id===deletionTarget);saveBackup('iz-backup-before-delete.json',list);break;}case'quick-export-all':saveBackup('iz-my-checks-backup.json',saved.campaigns);break;case'demo':openCase(demoCampaigns[0].id,true);break;case'open':openCase(el.dataset.id);break;case'analyst-open':openCase(el.dataset.id,false,true);break;case'scope':state.scope=el.dataset.scope;render();requestAnimationFrame(()=>restoreControlFocus('[data-action="scope"][data-scope="'+CSS.escape(state.scope)+'"]'));break;case'queue-next':{const next=queueCampaigns(allCampaigns(),saved.reviews,{filter:'pending',scope:state.scope,structuredReviews:saved.structuredReviews}).find(c=>c.id!==state.selectedId);if(next)openCase(next.id,false,true);else{navigate('campaigns');toast('Других дел в очереди нет.');}break;}case'back':navigate('campaigns');break;case'filter':state.filter=el.dataset.filter;render();requestAnimationFrame(()=>restoreControlFocus('[data-action="filter"][data-filter="'+CSS.escape(state.filter)+'"]'));break;case'stat':state.filter=el.dataset.filter;navigate('campaigns');break;case'detail-tab':state.detailsTab=el.dataset.tab;render();requestAnimationFrame(()=>restoreControlFocus('[data-action="detail-tab"][data-tab="'+CSS.escape(state.detailsTab)+'"]'));break;case'source-sensitivity':showSourceSensitivity();break;case'focus-source':focusSource(el.dataset.source);break;case'signal':{const c=campaignById(state.selectedId);const e=signalEvidence(c,el.dataset.signal).find(e=>state.demoStep===null||c.sources.slice(0,state.demoStep).some(s=>s.id===e.sourceId));if(e)focusSource(e.sourceId);else toast('В загруженных материалах нет явного указания на этот признак.');break;}case'demo-next':{const c=campaignById(state.selectedId);if(state.demoStep<c.sources.length){state.demoStep++;render();}else openCase(demoCampaigns[1].id);break;}case'demo-exit':state.demoStep=null;render();break;case'review':{const c=campaignById(state.selectedId);if(!c||state.demoStep!==null)break;const note=$('#review-note')?.value?.trim()||'';if(note.length<4){toast('Укажите, что осталось проверить.');$('#review-note')?.focus();break;}saved.reviews[c.id]=recordReview(c,saved.reviews[c.id],'later',note,{activeReviewMs:reviewClock.id===c.id?clockMs():null});clockPause();reviewDrafts.delete(c.id);const stored=persist();render();toast(stored?'Заметка сохранена. Дело остаётся в очереди.':storageError||'Данные не записаны. Экспортируйте дело перед закрытием страницы.');break;}case'split-original':{const original=campaignById(state.selectedId);if(!original||!canWrite())break;try{const copies=splitOriginalReferences(original);saved.campaigns.unshift(...copies);const stored=persist();openCase(copies[0].id,false,true);toast(stored?'Раздельные копии созданы. Исходное дело сохранено.':storageError);}catch(error){toast(error.message);}break;}case'append-material':openModal('text',state.selectedId);break;case'case-report':{const c={...campaignById(state.selectedId),relationships:campaignRelations(campaignById(state.selectedId),allCampaigns()),networkObservations:networkForCase(campaignById(state.selectedId))};download(`iz-report-${c.id}.html`,buildCaseReport(c,normalizeReview(saved.reviews[c.id]),saved.structuredReviews[c.id]),'text/html;charset=utf-8');toast('Отчёт скачан. Откройте файл и выберите печать для сохранения в PDF.');break;}case'export-case':download(`iz-${state.selectedId}.json`,{...exportCampaign(campaignById(state.selectedId)),exportedAt:new Date().toISOString()});toast('Дело экспортировано в JSON.');break;case'export-all':saveBackup('iz-campaigns-backup.json',allCampaigns());break;case'quality-retry':location.reload();break;case'export-metrics':if(qualityModule)download('iz-evaluation.json',statsReport());break;case'import-example':download('iz-feed-example.json',sampleFeed);break;case'modal-close':closeModal();break;case'modal-tab':if(!state.busy){rememberInputDraft();state.modalType=el.dataset.tab;state.files=[];renderModal();}break;case'remove-file':if(!state.busy){state.files.splice(Number(el.dataset.index),1);{const key=draftKey(visibleInputForm());if(key)inputDrafts.setFiles(key,state.files);}filesUI();}break;case'edit-source':editSource(el.dataset.source);break;}});
document.addEventListener('input',event=>{if(event.target.id==='review-note')reviewDrafts.set(state.selectedId,event.target.value);if(event.target.id==='consumer-search'){state.query=event.target.value;$('#consumer-history-list').innerHTML=consumerHistoryItems();}if(event.target.id==='case-search'){state.query=event.target.value;$('#campaign-table').innerHTML=caseTable(filtered());}});
document.addEventListener('change',event=>{if(event.target.id==='image-input')acceptFiles(event.target.files);if(event.target.id==='json-input'){state.files=Array.from(event.target.files).slice(0,1);filesUI();}});
function submitSourceEdit(event){
 event.preventDefault();
 try{
  const text=String(new FormData(event.target).get('text')||'').trim();
  if(!text||text.length>60000)throw new Error('Введите непустой текст источника длиной до 60 000 символов.');
  const campaign=saved.campaigns.find(c=>c.id===state.selectedId);
  const source=campaign?.sources.find(s=>s.id===state.editSourceId);
  if(!source)throw new Error('Источник больше не доступен. Закройте форму и откройте дело заново.');
  if(!canWrite())throw new Error(storageError);
  const previous=saved;
  const corrected={...source,originalText:source.originalText??source.text,text,correctedAt:new Date().toISOString()};
  saved={...saved,campaigns:saved.campaigns.map(c=>c.id===campaign.id?{...c,sources:c.sources.map(s=>s.id===source.id?corrected:s)}:c)};
  if(!persist()){
   saved=previous;campaignCache=null;
   throw new Error(storageError||'Исправление не сохранено. Текст оставлен в форме; повторите попытку или скопируйте его.');
  }
  closeModal();render();toast('Текст исправлен. Признаки пересчитаны; проверьте решение.');
 }catch(error){showError(error.message);$('#edit-form textarea')?.focus();}
}
document.addEventListener('submit',event=>{if(event.target.id==='quick-form')submitQuick(event);if(event.target.id==='check-form')submitCheck(event);if(event.target.id==='edit-form')submitSourceEdit(event);});
document.addEventListener('dragover',event=>{if(event.target.closest('#dropzone')){event.preventDefault();$('#dropzone').classList.add('dragover');}});
document.addEventListener('dragleave',event=>event.target.closest('#dropzone')?.classList.remove('dragover'));
document.addEventListener('drop',event=>{if(event.target.closest('#dropzone')){event.preventDefault();$('#dropzone').classList.remove('dragover');acceptFiles(event.dataTransfer.files);}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){const menu=document.getElementById('paper-mobile-menu'),toggle=document.querySelector('.paper-menu-toggle');if(menu&&!menu.hidden){menu.hidden=true;toggle?.setAttribute('aria-expanded','false');toggle?.setAttribute('aria-label','Открыть меню');toggle?.focus();}closeModal();}const modal=$('.modal');if(event.key==='Tab'&&modal){const items=Array.from(modal.querySelectorAll('button:not([disabled]),input:not([type="file"]),textarea,select,a[href]')).filter(el=>el.offsetParent!==null);if(items.length){if(event.shiftKey&&document.activeElement===items[0]){event.preventDefault();items.at(-1).focus();}else if(!event.shiftKey&&document.activeElement===items.at(-1)){event.preventDefault();items[0].focus();}}}if((event.key==='Enter'||event.key===' ')&&event.target.matches('tr[data-action],g[data-action]')){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
const initialRoute=location.hash.slice(1);if(['check','history','about','method','network','sources','campaigns'].includes(initialRoute))state.route=initialRoute;
window.addEventListener('hashchange',()=>{
 const route=location.hash.slice(1)||'overview';
 if(!['overview','check','history','about','method','network','sources','campaigns'].includes(route))return;
 if(state.busy){history.replaceState(null,'',state.route==='overview'?'#':'#'+state.route);return;}
 navigate(route);
});
